It doesn't look like the fix has made it into a stable release yet, but for now a delegating function can be used as a temporary workaround:

```typescript
export function myFunction(arg: any): any {
    return arg;
}
export function myFunction_1(arg: any): any {
    return myFunction(arg);
}

// Within AOT metadata compilation
myFunction(myFunction('some value')); // Throws recursion error
myFunction_1(myFunction('some value')); // Succeeds
```

I haven't tested this extensively, but it seems to be working for me so far.
